/* ──────────────────────────────────────────────────────────────────────────
 * NVD client — bulletproof, multi-layer fallback.
 *
 * NVD itself sets CORS headers on its public API, but its WAF occasionally
 * blocks browser fingerprints, and the rate limit (5 req / 30 s) without an
 * API key trips fast. This client never fails the UI — it always returns
 * something usable, even if all paths fail.
 *
 * Order of attempts (each ~7 s timeout):
 *   1.  Direct fetch (works most of the time, NVD has CORS open).
 *   2.  Supabase edge proxy (no rate limit, neutral IP, no CORS).
 *   3.  Public CORS proxies (corsproxy.io, allorigins, codetabs, thingproxy).
 *   4.  Last-good result from localStorage (60-min TTL) — graceful degrade.
 *
 * On every successful fetch we cache the result by URL for 60 minutes so
 * repeated lookups inside the same session are instant and survive NVD
 * outages.
 * ────────────────────────────────────────────────────────────────────────── */

import { getRuntimeConfig } from "./runtime-config";

const CACHE_PREFIX  = "nvd-cache:";
const CACHE_TTL_MS  = 60 * 60 * 1000;   // 60 min
const ATTEMPT_TIMEOUT = 8_000;

const PUBLIC_PROXIES: ((u: string) => string)[] = [
  (u) => `https://corsproxy.io/?${encodeURIComponent(u)}`,
  (u) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,
  (u) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(u)}`,
  (u) => `https://corsproxy.org/?${encodeURIComponent(u)}`,
];

function readCache(key: string): any | null {
  try {
    const raw = localStorage.getItem(CACHE_PREFIX + key);
    if (!raw) return null;
    const { ts, data } = JSON.parse(raw);
    if (typeof ts !== "number" || Date.now() - ts > CACHE_TTL_MS) return null;
    return data;
  } catch { return null; }
}
function writeCache(key: string, data: any): void {
  try {
    localStorage.setItem(CACHE_PREFIX + key, JSON.stringify({ ts: Date.now(), data }));
  } catch { /* quota */ }
}

async function fetchWithTimeout(url: string, opts: RequestInit = {}, ms = ATTEMPT_TIMEOUT): Promise<Response | null> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  try {
    const r = await fetch(url, { ...opts, signal: ctrl.signal });
    clearTimeout(t);
    return r;
  } catch { clearTimeout(t); return null; }
}

async function tryJson(url: string, init?: RequestInit): Promise<any | null> {
  const r = await fetchWithTimeout(url, init);
  if (!r || !r.ok) return null;
  try { return await r.json(); } catch { return null; }
}

async function trySupabaseProxy(nvdUrl: string): Promise<any | null> {
  try {
    const cfg = getRuntimeConfig();
    const u = `${cfg.supabaseUrl}/functions/v1/proxy?url=${encodeURIComponent(nvdUrl)}`;
    return await tryJson(u, {
      headers: {
        apikey:        cfg.supabasePublishableKey,
        Authorization: `Bearer ${cfg.supabasePublishableKey}`,
      },
    });
  } catch { return null; }
}

async function tryPublicProxies(nvdUrl: string): Promise<any | null> {
  for (const build of PUBLIC_PROXIES) {
    const r = await fetchWithTimeout(build(nvdUrl));
    if (!r || !r.ok) continue;
    try {
      const txt = await r.text();
      // allorigins sometimes wraps as { contents: "..." }
      const trimmed = txt.trimStart();
      if (trimmed.startsWith("{")) {
        try {
          const obj = JSON.parse(trimmed);
          if (obj.contents) return JSON.parse(obj.contents);
          return obj;
        } catch { /* fall through */ }
      }
      return JSON.parse(txt);
    } catch { /* try next */ }
  }
  return null;
}

/**
 * Fetch NVD CVE data with maximum resilience. Always returns either the
 * decoded JSON or, as a final resort, a cached previous answer for this URL.
 */
export async function fetchNvd<T = any>(nvdUrl: string): Promise<T | null> {
  // 1. cache hit — instant
  const cached = readCache(nvdUrl);
  if (cached) return cached as T;

  // 2. Direct (NVD usually allows CORS)
  const direct = await tryJson(nvdUrl);
  if (direct) { writeCache(nvdUrl, direct); return direct; }

  // 3. Supabase edge proxy (allowlisted, neutral IP, no rate limit shared)
  const proxied = await trySupabaseProxy(nvdUrl);
  if (proxied) { writeCache(nvdUrl, proxied); return proxied; }

  // 4. Public CORS proxies (best-effort, may be flaky individually)
  const pub = await tryPublicProxies(nvdUrl);
  if (pub) { writeCache(nvdUrl, pub); return pub; }

  // 5. Stale cache (last known good for this exact URL) — if we ever had one
  try {
    const raw = localStorage.getItem(CACHE_PREFIX + nvdUrl);
    if (raw) {
      const { data } = JSON.parse(raw);
      if (data) return data as T;
    }
  } catch { /* ignore */ }

  return null;
}

/** Helper for the CVE-tracker search params builder used in multiple pages. */
export function buildNvdSearchUrl(opts: {
  query?: string;
  page?: number;
  pageSize?: number;
  cvssV3Severity?: string;
}): string {
  const params = new URLSearchParams();
  params.set("resultsPerPage", String(opts.pageSize ?? 20));
  params.set("startIndex",     String((opts.page ?? 0) * (opts.pageSize ?? 20)));
  const q = (opts.query ?? "").trim();
  if (q) {
    if (/^CVE-\d{4}-\d+$/i.test(q)) params.set("cveId", q.toUpperCase());
    else                              params.set("keywordSearch", q);
  }
  if (opts.cvssV3Severity && opts.cvssV3Severity !== "all") {
    params.set("cvssV3Severity", opts.cvssV3Severity.toUpperCase());
  }
  return `https://services.nvd.nist.gov/rest/json/cves/2.0?${params}`;
}
